 proof=json.loads((O/'dynamo-test.json').read_text());assert proof['passed'] and proof['isolatedTableDeleted'];assert json.loads(pathlib.Path('/private/tmp/sharing76-browser.log').read_text())['passed']
 s=m.session();l=s.client('lambda');cf=s.client('cloudformation');iam=s.client('iam');inv=json.loads((O/'inventory.json').read_text());prep=json.loads((O/'preparation.json').read_text());result={'part':76,'functions':[],'stacks':[],'applicationDataWrites':False,'financialActivation':False}
