 out=l.invoke(FunctionName=inv['writer']['name'],Payload=b'{"httpMethod":"POST","resource":"/orders/commercial-preview","headers":{},"body":"{}"}');body=json.loads(out['Payload'].read());assert not out.get('FunctionError') and body['statusCode'] in [401,409,503];result['anonymousChecks']={'staff':401,'writer':body['statusCode']};save();print(json.dumps({'anonymousChecks':result['anonymousChecks'],'financialActivation':False}))
